CREATE SCHEMA control_plane;
REVOKE ALL ON SCHEMA control_plane FROM PUBLIC;
CREATE FUNCTION control_plane.is_canonical_origin(value text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog AS $$
DECLARE authority text; host text; port_text text; final_label text;
BEGIN
  IF octet_length(value)>255 OR value !~ '^https://[a-z0-9.-]+(?::[0-9]+)?$' OR value ~ '[^\x00-\x7F]' THEN RETURN false; END IF;
  authority := substring(value FROM 9);
  port_text := substring(authority FROM ':([0-9]+)$');
  host := CASE WHEN port_text IS NULL THEN authority ELSE left(authority, -(length(port_text) + 1)) END;
  IF length(host)>253 OR host !~ '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)*$' THEN RETURN false; END IF;
  final_label := regexp_replace(host, '^.*\.', '');
  IF final_label !~ '[a-z]' THEN RETURN false; END IF;
  IF host ~ '^(?:0x[0-9a-f]+|[0-9]+)(?:\.(?:0x[0-9a-f]+|[0-9]+)){0,3}$' THEN RETURN false; END IF;
  IF port_text IS NOT NULL THEN
    IF length(port_text)>5 OR port_text ~ '^0' THEN RETURN false; END IF;
    IF port_text::integer NOT BETWEEN 1 AND 65535 OR port_text::integer=443 THEN RETURN false; END IF;
  END IF;
  RETURN true;
END $$;
CREATE TABLE control_plane.schema_migrations (id text CONSTRAINT schema_migrations_pkey PRIMARY KEY, checksum bytea NOT NULL CONSTRAINT schema_migrations_checksum_length CHECK (octet_length(checksum)=32), applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control_plane.encrypted_envelopes (id uuid CONSTRAINT encrypted_envelopes_pkey PRIMARY KEY, envelope_key_id text NOT NULL CONSTRAINT encrypted_envelopes_key_format CHECK(envelope_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), nonce bytea NOT NULL CONSTRAINT encrypted_envelopes_nonce_length CHECK(octet_length(nonce)=12), ciphertext bytea NOT NULL CONSTRAINT encrypted_envelopes_ciphertext_length CHECK(octet_length(ciphertext)>=16), purpose text NOT NULL CONSTRAINT encrypted_envelopes_purpose CHECK(purpose IN ('did','policy')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT encrypted_envelopes_key_nonce_key UNIQUE(envelope_key_id,nonce));
CREATE TABLE control_plane.did_mappings (id uuid CONSTRAINT did_mappings_pkey PRIMARY KEY, sector text NOT NULL CONSTRAINT did_mappings_sector_origin CHECK(control_plane.is_canonical_origin(sector)), subject_key_id text NOT NULL CONSTRAINT did_mappings_subject_key_format CHECK(subject_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), subject text NOT NULL CONSTRAINT did_mappings_subject_format CHECK(subject ~ '^[A-Za-z0-9_-]{43}$'), envelope_id uuid NOT NULL CONSTRAINT did_mappings_envelope_fkey REFERENCES control_plane.encrypted_envelopes(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), erased_at timestamptz, CONSTRAINT did_mappings_erased_order CHECK(erased_at IS NULL OR erased_at>=created_at), CONSTRAINT did_mappings_sector_subject_key UNIQUE(sector,subject));
CREATE TABLE control_plane.login_states (id uuid CONSTRAINT login_states_pkey PRIMARY KEY, state_digest bytea NOT NULL CONSTRAINT login_states_digest_key UNIQUE CONSTRAINT login_states_digest_length CHECK(octet_length(state_digest)=32), binding_key_id text NOT NULL CONSTRAINT login_states_binding_key_format CHECK(binding_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), binding_fingerprint bytea NOT NULL CONSTRAINT login_states_binding_length CHECK(octet_length(binding_fingerprint)=32), return_origin text NOT NULL CONSTRAINT login_states_return_origin CHECK(control_plane.is_canonical_origin(return_origin)), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, consumed_at timestamptz, CONSTRAINT login_states_lifecycle CHECK(expires_at=created_at+interval '5 minutes' AND (consumed_at IS NULL OR consumed_at BETWEEN created_at AND expires_at)));
CREATE TABLE control_plane.identity_sessions (id uuid CONSTRAINT identity_sessions_pkey PRIMARY KEY, binding_key_id text NOT NULL CONSTRAINT identity_sessions_binding_key_format CHECK(binding_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), binding_fingerprint bytea NOT NULL CONSTRAINT identity_sessions_binding_length CHECK(octet_length(binding_fingerprint)=32), mapping_id uuid NOT NULL CONSTRAINT identity_sessions_mapping_fkey REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT, origin text NOT NULL CONSTRAINT identity_sessions_origin CHECK(control_plane.is_canonical_origin(origin)), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), last_seen_at timestamptz NOT NULL, idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, revoked_at timestamptz, CONSTRAINT identity_sessions_lifecycle CHECK(last_seen_at>=created_at AND last_seen_at<=absolute_expires_at AND idle_expires_at=LEAST(last_seen_at+interval '5 minutes',absolute_expires_at) AND absolute_expires_at=created_at+interval '15 minutes' AND (revoked_at IS NULL OR revoked_at BETWEEN created_at AND absolute_expires_at+interval '30 seconds')), CONSTRAINT identity_sessions_binding_key UNIQUE(binding_key_id,binding_fingerprint));
CREATE TABLE control_plane.proof_challenges (id uuid CONSTRAINT proof_challenges_pkey PRIMARY KEY, challenge_key_id text NOT NULL CONSTRAINT proof_challenges_key_format CHECK(challenge_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), challenge_fingerprint bytea NOT NULL CONSTRAINT proof_challenges_fingerprint_length CHECK(octet_length(challenge_fingerprint)=32), binding_key_id text NOT NULL CONSTRAINT proof_challenges_binding_key_format CHECK(binding_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), binding_fingerprint bytea NOT NULL CONSTRAINT proof_challenges_binding_length CHECK(octet_length(binding_fingerprint)=32), mapping_id uuid NOT NULL CONSTRAINT proof_challenges_mapping_fkey REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT, jkt bytea NOT NULL CONSTRAINT proof_challenges_jkt_length CHECK(octet_length(jkt)=32), audience text NOT NULL CONSTRAINT proof_challenges_audience CHECK(audience='dsa-signal'), origin text NOT NULL CONSTRAINT proof_challenges_origin CHECK(control_plane.is_canonical_origin(origin)), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, consumed_at timestamptz, CONSTRAINT proof_challenges_lifecycle CHECK(expires_at>created_at AND expires_at<=created_at+interval '120 seconds' AND (consumed_at IS NULL OR consumed_at BETWEEN created_at AND expires_at)), CONSTRAINT proof_challenges_key_fingerprint_key UNIQUE(challenge_key_id,challenge_fingerprint));
CREATE TABLE control_plane.policy_snapshots (id uuid CONSTRAINT policy_snapshots_pkey PRIMARY KEY, digest bytea NOT NULL CONSTRAINT policy_snapshots_digest_key UNIQUE CONSTRAINT policy_snapshots_digest_length CHECK(octet_length(digest)=32), envelope_id uuid NOT NULL CONSTRAINT policy_snapshots_envelope_fkey REFERENCES control_plane.encrypted_envelopes(id) ON DELETE RESTRICT, version text NOT NULL CONSTRAINT policy_snapshots_version_key UNIQUE CONSTRAINT policy_snapshots_version_format CHECK(version ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), signed_at timestamptz NOT NULL, verified_at timestamptz NOT NULL, fresh_until timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT policy_snapshots_times CHECK(signed_at<=verified_at AND verified_at<=created_at AND fresh_until>=created_at));
CREATE TABLE control_plane.active_policy (singleton boolean DEFAULT true CONSTRAINT active_policy_pkey PRIMARY KEY CONSTRAINT active_policy_singleton CHECK(singleton), snapshot_id uuid NOT NULL CONSTRAINT active_policy_snapshot_fkey REFERENCES control_plane.policy_snapshots(id) ON DELETE RESTRICT, activated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE control_plane.jti_uses (id uuid CONSTRAINT jti_uses_pkey PRIMARY KEY, policy_snapshot_id uuid NOT NULL CONSTRAINT jti_uses_snapshot_fkey REFERENCES control_plane.policy_snapshots(id) ON DELETE RESTRICT, credential_expires_at timestamptz NOT NULL, retained_until timestamptz NOT NULL, decision_clock timestamptz NOT NULL, decision text NOT NULL CONSTRAINT jti_uses_decision CHECK(decision IN ('authorized','rejected')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), CONSTRAINT jti_uses_lifecycle CHECK(credential_expires_at>decision_clock AND credential_expires_at<=decision_clock+interval '900 seconds' AND retained_until=credential_expires_at+interval '30 seconds' AND created_at>=decision_clock));
CREATE TABLE control_plane.jti_key_aliases (jti_use_id uuid NOT NULL CONSTRAINT jti_aliases_use_fkey REFERENCES control_plane.jti_uses(id) ON DELETE CASCADE, key_id text NOT NULL CONSTRAINT jti_aliases_key_format CHECK(key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), fingerprint bytea NOT NULL CONSTRAINT jti_aliases_fingerprint_length CHECK(octet_length(fingerprint)=32), CONSTRAINT jti_aliases_pkey PRIMARY KEY(jti_use_id,key_id), CONSTRAINT jti_aliases_key_fingerprint_key UNIQUE(key_id,fingerprint));
CREATE TABLE control_plane.idempotency_results (id uuid CONSTRAINT idempotency_results_pkey PRIMARY KEY, request_key_id text NOT NULL CONSTRAINT idempotency_results_key_format CHECK(request_key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), request_fingerprint bytea NOT NULL CONSTRAINT idempotency_results_fingerprint_length CHECK(octet_length(request_fingerprint)=32), response_status smallint NOT NULL, result text NOT NULL CONSTRAINT idempotency_results_result CHECK(result IN ('authorized','rejected')), error_code text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, CONSTRAINT idempotency_results_wire CHECK(expires_at=created_at+interval '60 seconds' AND ((response_status=200 AND result='authorized' AND error_code IS NULL) OR (response_status IN (400,406,413,415) AND result='rejected' AND error_code='invalid_request') OR (response_status=401 AND result='rejected' AND error_code='rejected') OR (response_status=409 AND result='rejected' AND error_code='conflict') OR (response_status=503 AND result='rejected' AND error_code='unavailable'))));
CREATE TABLE control_plane.idempotency_key_aliases (result_id uuid NOT NULL CONSTRAINT idempotency_aliases_result_fkey REFERENCES control_plane.idempotency_results(id) ON DELETE CASCADE, key_id text NOT NULL CONSTRAINT idempotency_aliases_key_format CHECK(key_id ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), fingerprint bytea NOT NULL CONSTRAINT idempotency_aliases_fingerprint_length CHECK(octet_length(fingerprint)=32), CONSTRAINT idempotency_aliases_pkey PRIMARY KEY(result_id,key_id), CONSTRAINT idempotency_aliases_key_fingerprint_key UNIQUE(key_id,fingerprint));
CREATE TABLE control_plane.entitlements (id uuid CONSTRAINT entitlements_pkey PRIMARY KEY, mapping_id uuid NOT NULL CONSTRAINT entitlements_mapping_fkey REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT, jkt bytea NOT NULL CONSTRAINT entitlements_jkt_length CHECK(octet_length(jkt)=32), entitlement text NOT NULL CONSTRAINT entitlements_kind CHECK(entitlement='chat'), status text NOT NULL CONSTRAINT entitlements_status CHECK(status IN ('active','revoked')), policy_snapshot_id uuid NOT NULL CONSTRAINT entitlements_snapshot_fkey REFERENCES control_plane.policy_snapshots(id) ON DELETE RESTRICT, policy_version text NOT NULL CONSTRAINT entitlements_version_format CHECK(policy_version ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$'), authorized_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, reason text NOT NULL CONSTRAINT entitlements_reason CHECK(reason IN ('membership_verified','membership_missing','policy_stale','credential_expired','revoked')), CONSTRAINT entitlements_lifecycle CHECK(expires_at>authorized_at AND expires_at<=authorized_at+interval '900 seconds' AND ((status='active' AND revoked_at IS NULL) OR (status='revoked' AND revoked_at>=authorized_at))), CONSTRAINT entitlements_mapping_jkt_kind_key UNIQUE(mapping_id,jkt,entitlement));
CREATE TABLE control_plane.security_audit_events (id uuid CONSTRAINT security_audit_events_pkey PRIMARY KEY, event_type text NOT NULL CONSTRAINT security_audit_events_type CHECK(event_type IN ('login_state_consumed','session_revoked','challenge_consumed','entitlement_decided','policy_activated')), outcome text NOT NULL CONSTRAINT security_audit_events_outcome CHECK(outcome IN ('success','denied','error')), reason text NOT NULL CONSTRAINT security_audit_events_reason CHECK(reason IN ('completed','expired','revoked','policy','authorization')), mapping_id uuid CONSTRAINT security_audit_events_mapping_fkey REFERENCES control_plane.did_mappings(id) ON DELETE RESTRICT, snapshot_id uuid CONSTRAINT security_audit_events_snapshot_fkey REFERENCES control_plane.policy_snapshots(id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION control_plane.active_policy_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog, control_plane AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM control_plane.policy_snapshots WHERE id=NEW.snapshot_id AND verified_at<=NEW.activated_at AND fresh_until>NEW.activated_at) THEN RAISE EXCEPTION 'active policy must be verified and fresh at activation'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER active_policy_activation AFTER INSERT OR UPDATE ON control_plane.active_policy DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION control_plane.active_policy_guard();
CREATE FUNCTION control_plane.envelope_purpose_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog, control_plane AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM control_plane.encrypted_envelopes WHERE id=NEW.envelope_id AND purpose=CASE TG_TABLE_NAME WHEN 'did_mappings' THEN 'did' ELSE 'policy' END) THEN RAISE EXCEPTION 'envelope purpose does not match reference'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER did_mapping_envelope_purpose AFTER INSERT OR UPDATE ON control_plane.did_mappings DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION control_plane.envelope_purpose_guard();
CREATE CONSTRAINT TRIGGER policy_snapshot_envelope_purpose AFTER INSERT OR UPDATE ON control_plane.policy_snapshots DEFERRABLE INITIALLY IMMEDIATE FOR EACH ROW EXECUTE FUNCTION control_plane.envelope_purpose_guard();
CREATE FUNCTION control_plane.audit_mutation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF TG_OP='DELETE' AND has_table_privilege(current_user,'control_plane.security_audit_events','DELETE') THEN RETURN OLD; END IF; RAISE EXCEPTION 'audit events are append-only'; END $$;
CREATE TRIGGER security_audit_append_only BEFORE UPDATE OR DELETE ON control_plane.security_audit_events FOR EACH ROW EXECUTE FUNCTION control_plane.audit_mutation_guard();
CREATE INDEX login_states_expiry_idx ON control_plane.login_states(expires_at); CREATE INDEX sessions_idle_expiry_idx ON control_plane.identity_sessions(idle_expires_at); CREATE INDEX sessions_absolute_expiry_idx ON control_plane.identity_sessions(absolute_expires_at); CREATE INDEX challenges_expiry_idx ON control_plane.proof_challenges(expires_at); CREATE INDEX jtis_retained_idx ON control_plane.jti_uses(retained_until); CREATE INDEX idempotency_expiry_idx ON control_plane.idempotency_results(expires_at); CREATE INDEX entitlement_expiry_idx ON control_plane.entitlements(expires_at); CREATE INDEX audit_occurred_idx ON control_plane.security_audit_events(occurred_at);
REVOKE ALL ON ALL TABLES IN SCHEMA control_plane FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA control_plane FROM PUBLIC;
CREATE FUNCTION control_plane.cleanup_expired(audit_before timestamptz) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog, control_plane AS $$
DECLARE removed bigint := 0; affected bigint;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(8004);
  IF audit_before > clock_timestamp()-interval '90 days' THEN RAISE EXCEPTION 'audit retention is 90 days'; END IF;
  DELETE FROM control_plane.login_states WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.proof_challenges WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.identity_sessions WHERE absolute_expires_at+interval '30 seconds'<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.idempotency_results WHERE expires_at<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.jti_uses WHERE retained_until<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.entitlements WHERE expires_at+interval '30 seconds'<=clock_timestamp(); GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  DELETE FROM control_plane.security_audit_events WHERE occurred_at<audit_before; GET DIAGNOSTICS affected=ROW_COUNT; removed:=removed+affected;
  RETURN removed;
END $$;
REVOKE ALL ON FUNCTION control_plane.cleanup_expired(timestamptz) FROM PUBLIC;
REVOKE ALL ON SCHEMA control_plane FROM PUBLIC;
